import{c as l,Z as s,Q as e,j as i,m as a,g as r,n as o,o as d,av as h}from"./chunks/framework.rWdQudnF.js";const f=JSON.parse('{"title":"软件架构概述","description":"","frontmatter":{"title":"软件架构概述"},"headers":[],"relativePath":"综合知识/架构设计/软件架构概述/index.md","filePath":"综合知识/架构设计/软件架构概述/index.md","lastUpdated":null}'),g={name:"综合知识/架构设计/软件架构概述/index.md"};function p(u,t,b,c,q,k){const n=s("font");return e(),i("div",null,[t[4]||(t[4]=a('<h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="软件架构的概念" tabindex="-1">软件架构的概念 <a class="header-anchor" href="#软件架构的概念" aria-label="Permalink to &quot;软件架构的概念&quot;">​</a></h3><p>一个程序和计算系统软件体系结构是指系统的一个或者多个结构。结构中包括<strong>软件的构件，构件的外部可见属性以及它们之间的相互关系</strong>。</p><p>体系结构并非可运行软件。确切地说，它是一种表达，使软件工程师能够：</p><ul><li>(1)分析设计在满足所规定的需求方面的有效性；</li><li>(2)在设计变更相对容易的阶段，考虑体系结构可能的选择方案；</li><li>(3)降低与软件构造相关联的风险。</li></ul><p>上面的定义强调在任意体系结构的表述中“软件构件”的角色。软件构件简单到<strong>可以是程序模块或者面向对象的类</strong>，也可以扩充到包含数据库和能够完成客户与服务器网络配置的“中间件”。</p><p>软件体系结构的设计两个层次：<strong>数据设计和体系结构设计</strong>。</p>',7)),r("ul",null,[t[3]||(t[3]=r("li",null,"数据设计体现传统系统中体系结构的数据构件和面向对象系统中类的定义（封装了属性和操作），",-1)),r("li",null,[t[1]||(t[1]=o("体系结构设计则主要",-1)),d(n,{color:"#f79646"},{default:h(()=>[...t[0]||(t[0]=[o("关注软件构件的结构、属性和交互作用",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))])]),t[5]||(t[5]=a('<hr><blockquote><p>软件架构设计主要关注软件构件的<strong>结构</strong>、<strong>属性</strong>和<strong>交互作用</strong>，并通过多种<strong>视图</strong>全面描述特定系统的架构。</p></blockquote><ul><li><strong>结构</strong>：系统的组成构件</li><li><strong>属性</strong>：构件的特征描述</li><li><strong>交互作用</strong>：构件之间的协作关系</li><li><strong>视图</strong>：从不同视角描述架构的不同方面</li></ul><h3 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h3><h4 id="架构设计生命周期" tabindex="-1">架构设计生命周期 <a class="header-anchor" href="#架构设计生命周期" aria-label="Permalink to &quot;架构设计生命周期&quot;">​</a></h4><table tabindex="0"><thead><tr><th>阶段</th><th>主要关注</th></tr></thead><tbody><tr><td><strong>需求分析</strong></td><td>需求获取、场景描述、质量属性定义</td></tr><tr><td><strong>设计阶段</strong></td><td>架构模型描述、设计分析方法、设计经验总结与复用</td></tr><tr><td><strong>实现阶段</strong></td><td>从架构向代码的过渡、开发过程支持、测试技术</td></tr><tr><td><strong>构件组装</strong></td><td>检测并解决架构失配问题</td></tr><tr><td><strong>部署阶段</strong></td><td>架构到物理硬件的映射、构件部署配置、资源分配、部署描述与环境初始化</td></tr><tr><td><strong>后开发阶段</strong></td><td>架构演化、运维监控、重构、技术债务管理、架构恢复与评估</td></tr></tbody></table><ul><li><a href="/arch-exam/综合知识/架构设计/软件架构概述/架构设计生命周期.html">架构设计- 软件架构概述 架构设计生命周期</a></li></ul><h4 id="架构设计概念" tabindex="-1">架构设计概念 <a class="header-anchor" href="#架构设计概念" aria-label="Permalink to &quot;架构设计概念&quot;">​</a></h4><p>从<strong>需求分析到软件设计之间的过渡过程</strong>称为软件架构。只要软件架构设计好了，整个软件就不会出现坍塌性的错误，即不会崩溃。</p><p>架构设计就是需求分配，将满足需求的职责分配到组件上。软件架构为软件系统提供了一个结构、行为和属性的高级抽象，由构件的描述、构件的相互作用(连接件)、指导构件集成的模式以及这些模式的约束组成。</p><p>软件架构不仅指定了系统的组织结构和拓扑结构，并且显示了系统需求和构件之间的对应关系，提供了一些设计决策的基本原理。<strong>解决好软件的复用、质量和维护问题</strong>，是研究软件架构的根本目的。</p><p>软件架构设计包括<strong>提出架构模型，产生架构设计和进行设计评审等活动</strong>，是一个迭代的过程。架构设计主要关注<strong>软件组件的结构、属性和交互作用，并通过多种视图</strong>全面描述特定系统的架构。</p><hr><p>架构设计是一个迭代过程，包括三大活动：</p><ol><li><strong>提出架构模型</strong> — 选择架构风格，建立初始架构</li><li><strong>产生架构设计</strong> — 将构件映射到架构，分析构件关系</li><li><strong>进行设计评审</strong> — 邀请独立外部人员评审</li></ol><blockquote><p>❌ 易错：架构设计活动<strong>不包含</strong>&quot;设计并实现这些构件&quot;（实现属于后续阶段）</p></blockquote><h4 id="架构设计的主要作用" tabindex="-1">架构设计的主要作用 <a class="header-anchor" href="#架构设计的主要作用" aria-label="Permalink to &quot;架构设计的主要作用&quot;">​</a></h4><p>软件架构能够在设计变更相对容易的阶段，考虑系统结构的可选方案，<strong>便于技术人员与非技术人员就软件设计进行交互</strong>，能够展现软件的结构、属性与内部交互关系。</p><p>软件架构是项目干系人进行交流的手段，明确了对系统实现的约束条件，决定了开发和维护组织的组织结构，制约着系统的质量属性。</p><p>软件架构使推理和控制的更改更加简单，有助于循序渐进的原型设计，可以作为培训的基础。</p><p>软件架构是可传递和可复用的模型，通过研究软件架构可能预测软件的质量。</p><hr><ol><li>解决相对复杂的需求分析问题</li><li>解决<strong>非功能属性</strong>在系统占据重要位置的设计问题</li><li>解决生命周期长、扩展性需求高的系统整体结构问题</li></ol><blockquote><p>❌ 注意：架构设计<strong>不负责</strong>系统代码实现的具体细节</p></blockquote><h4 id="架构设计目标" tabindex="-1">架构设计目标 <a class="header-anchor" href="#架构设计目标" aria-label="Permalink to &quot;架构设计目标&quot;">​</a></h4><blockquote><p>软件架构设计的主要目标是获得一个同时满足<strong>功能性需求</strong>和<strong>非功能性需求</strong>的软件系统框架模型</p></blockquote><h4 id="需求模型-→-架构模型转换-★" tabindex="-1">需求模型 → 架构模型转换 ★ <a class="header-anchor" href="#需求模型-→-架构模型转换-★" aria-label="Permalink to &quot;需求模型 → 架构模型转换 ★&quot;">​</a></h4><blockquote><p>两个核心问题：① <strong>如何构建架构模型</strong> ② <strong>如何保证模型转换的可追踪性</strong></p></blockquote><hr><h3 id="构件" tabindex="-1">构件 <a class="header-anchor" href="#构件" aria-label="Permalink to &quot;构件&quot;">​</a></h3><p>构件是<strong>一个独立可交付的功能单元，外界通过接口访问其提供的服务</strong>。</p><p>构件<strong>由一组通常需要同时部署的原子构件组成</strong>。一个原子构件是一个模块和一组资源。原子构件是部署、版本控制和替换的基本单位。原子构件通常成组地部署，但是它也能够被单独部署。</p><p>构件和原子构件之间的区别在于，<strong>大多数原子构件永远都不会被单独部署</strong>，尽管它们<strong>可以被单独部署</strong>。相反，大多数原子构件都属于一个构件家族，一次部署往往涉及整个家族。</p><p>一个模块是<strong>不带单独资源的原子构件</strong>（在这个严格定义下，<strong>Java包不是模块</strong>一一在Java中部署的原子单元是类文件。一个单独的包被编译成多个单独的类文件一一每个公共类都有一个)。</p><p>模块是一组类和可能的非面向对象的结构体，比如过程或者函数。</p><h4 id="构件和对象" tabindex="-1">构件和对象 <a class="header-anchor" href="#构件和对象" aria-label="Permalink to &quot;构件和对象&quot;">​</a></h4><p>构件的特性是：</p><ul><li>(1)独立部署单元；</li><li>(2)作为第三方的组装单元；</li><li>(3)没有（外部的）可见状态。</li></ul><p>一个构件可以<strong>包含多个类元素</strong>，但是一个类元素只能属于一个构件。将一个类拆分进行部署通常没什么意义。</p><p>对象的特性是：</p><ul><li>(1)一个实例单元，具有唯一的标志。</li><li>(2)可能具有状态，此状态外部可见。</li><li>(3)封装了自己的状态和行为。</li></ul><h4 id="构件接口" tabindex="-1">构件接口 <a class="header-anchor" href="#构件接口" aria-label="Permalink to &quot;构件接口&quot;">​</a></h4><p>接口标准化是对接口中消息的格式、模式和协议的标准化。它不是要将接口格式化为参数化操作的集合，而是<strong>关注输入输出的消息的标准化</strong>，它强调当机器在网络中互连时，标准的消息模式、格式、协议的重要性。</p><h4 id="面向构件的编程-cop" tabindex="-1">面向构件的编程(COP) <a class="header-anchor" href="#面向构件的编程-cop" aria-label="Permalink to &quot;面向构件的编程(COP)&quot;">​</a></h4><p>关注于如何支持建立面向构件的解决方案。“面向构件的编程需要下列基本的支持：</p><p>一一多态性（可替代性）： 一一模块封装性（高层次信息的隐藏）： 一一后期的绑定和装载（部署独立性）： 一一安全性（类型和模块安全性）。”</p><h4 id="构件组装失配类型-★" tabindex="-1">构件组装失配类型 ★ <a class="header-anchor" href="#构件组装失配类型-★" aria-label="Permalink to &quot;构件组装失配类型 ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th>失配类型</th><th>原因</th></tr></thead><tbody><tr><td><strong>构件级失配</strong></td><td>对构件基础设施、控制模型、数据模型的假设冲突</td></tr><tr><td><strong>连接子级失配</strong></td><td>对构件交互协议、构件连接时数据格式的假设冲突</td></tr></tbody></table><blockquote><p>❌ 易错：不包括&quot;构件操作不当引起的失配&quot;</p></blockquote><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><h4 id="非功能性需求四分类-★" tabindex="-1">非功能性需求四分类 ★ <a class="header-anchor" href="#非功能性需求四分类-★" aria-label="Permalink to &quot;非功能性需求四分类 ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td><strong>操作性需求</strong></td><td>系统运行环境与变化</td><td>支持主流标准协议</td></tr><tr><td><strong>性能需求</strong></td><td>响应时间、吞吐量</td><td>响应 ≤ 3s</td></tr><tr><td><strong>安全性需求</strong></td><td>防中断、防数据丢失</td><td>密码加密、超时重登</td></tr><tr><td><strong>文化需求</strong></td><td>文化背景相关</td><td>多语言支持</td></tr></tbody></table><h4 id="基于架构的软件开发方法-absd" tabindex="-1">基于架构的软件开发方法 ABSD <a class="header-anchor" href="#基于架构的软件开发方法-absd" aria-label="Permalink to &quot;基于架构的软件开发方法 ABSD&quot;">​</a></h4><p>见下一个章节</p><h4 id="dssa-特定领域软件架构-三层模型" tabindex="-1">DSSA（特定领域软件架构）三层模型 <a class="header-anchor" href="#dssa-特定领域软件架构-三层模型" aria-label="Permalink to &quot;DSSA（特定领域软件架构）三层模型&quot;">​</a></h4><p>具体见下一个章节</p><p>DSSA就是专用于一类特定类型的任务（领域）的、在整个领域中能有效地使用的、为成功构造应用系统<strong>限定了标准的组合结构的软件构件的集合</strong>。</p><p>DSSA就是一个特定的问题领域中支持一组应用的领域模型、参考需求、参考架构等组成的开发基础，其目标就是支持在一个特定领域中多个应用的生成。</p><ul><li>垂直域：在一个特定领域中的通用的软件架构，是一个完整的架构。</li><li>水平域：在多个不同的特定领域之间的相同的部分的小工具（如购物和教育都有收费系统，收费系统即是水平域)。</li></ul><hr><blockquote><p>DSSA 是为一个特定应用领域中一组应用<strong>提供组织结构参考的标准软件体系结构</strong></p></blockquote><p><strong>三层模型：</strong></p><ol><li><strong>领域开发环境</strong> — 顶层，领域设计人员工作环境</li><li><strong>领域特定应用开发环境</strong> — 中间层，应用开发人员工作环境</li><li><strong>应用执行环境</strong> — 底层，最终用户运行环境</li></ol><h4 id="软件系统四项基本功能" tabindex="-1">软件系统四项基本功能 <a class="header-anchor" href="#软件系统四项基本功能" aria-label="Permalink to &quot;软件系统四项基本功能&quot;">​</a></h4><ol><li><strong>数据存储</strong> — 数据持久化存储与检索（data storage/persistence）</li><li><strong>数据访问逻辑</strong> — 处理数据的逻辑，通常是 SQL 查询</li><li><strong>应用逻辑（业务逻辑）</strong> — DFD、用例、功能需求中记录的逻辑</li><li><strong>表示逻辑</strong> — 用户界面显示与命令接收</li></ol><p><strong>三类主要硬件构件：</strong> 客户端、服务器、网络</p><h4 id="es-与-dss" tabindex="-1">ES 与 DSS <a class="header-anchor" href="#es-与-dss" aria-label="Permalink to &quot;ES 与 DSS&quot;">​</a></h4><ul><li><strong>专家系统（ES）</strong>：与一般系统的根本区别在于能<strong>解释推理过程</strong></li><li><strong>决策支持系统（DSS）</strong>：主要用于解决<strong>半结构化问题</strong></li></ul><h4 id="设计经验重用技术" tabindex="-1">设计经验重用技术 <a class="header-anchor" href="#设计经验重用技术" aria-label="Permalink to &quot;设计经验重用技术&quot;">​</a></h4><blockquote><p>用于总结和重用设计经验的主要技术：<strong>体系结构风格和DSSA</strong></p></blockquote><hr><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ul><li><a href="/arch-exam/综合知识/架构设计/软件架构概述/架构概述 练习题.html">架构设计- 软件架构概述 练习题</a></li></ul>',73))])}const x=l(g,[["render",p]]);export{f as __pageData,x as default};
